import{_ as l,a0 as m,w as d,s as i,ao as a,I as o,x as t,a1 as p,A as r}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const f=JSON.parse('{"title":"RHCSA 系列（九）: Yum 包管理、Cron 自动任务计划和监控系统日志 | LCTT x X-CMD","titleTemplate":false,"description":"RHCSA 系列（九）: Yum 包管理、Cron 自动任务计划和监控系统日志 | LCTT (RHCSA Series) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"RHCSA 系列（九）: Yum 包管理、Cron 自动任务计划和监控系统日志 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"RHCSA 系列（九）: Yum 包管理、Cron 自动任务计划和监控系统日志 | LCTT (RHCSA Series) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"RHCSA Series/RHCSA Series--Part 10--Yum Package Management, Automating Tasks with Cron and Monitoring System Logs","title":"RHCSA 系列（九）: Yum 包管理、Cron 自动任务计划和监控系统日志","tag":"RHCSA Series","desc":""},"relativePath":"RHCSA Series/RHCSA Series--Part 10--Yum Package Management, Automating Tasks with Cron and Monitoring System Logs.md","filePath":"[post].md"}'),s={name:"RHCSA Series/RHCSA Series--Part 10--Yum Package Management, Automating Tasks with Cron and Monitoring System Logs.md"};function c(u,e,g,w,C,y){const n=m("Link");return d(),i("div",null,[e[22]||(e[22]=a(`<h1 id="rhcsa-系列-九-yum-包管理、cron-自动任务计划和监控系统日志" tabindex="-1">RHCSA 系列（九）: Yum 包管理、Cron 自动任务计划和监控系统日志 <a class="header-anchor" href="#rhcsa-系列-九-yum-包管理、cron-自动任务计划和监控系统日志" aria-label="Permalink to “RHCSA 系列（九）: Yum 包管理、Cron 自动任务计划和监控系统日志”">​</a></h1><p>在这篇文章中，我们将回顾如何在 RHEL7 中安装，更新和删除软件包。我们还将介绍如何使用 cron 进行任务自动化，并完成如何查找和监控系统日志文件，以及为什么这些技能是系统管理员必备技能。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/05/Yum-Package-Management-Cron-Job-Log-Monitoring-Linux.jpg" alt="Yum Package Management Cron Jobs Log Monitoring Linux"></p><p><em>RHCSA: Yum包管理、任务计划和系统监控 – Part 10</em></p><h3 id="使用yum-管理包" tabindex="-1">使用yum 管理包 <a class="header-anchor" href="#使用yum-管理包" aria-label="Permalink to “使用yum 管理包”">​</a></h3><p>要安装一个包以及所有尚未安装的依赖包，您可以使用：</p><pre><code># yum -y install package_name(s)
</code></pre><p>package_name(s) 需要是至少一个真实的软件包名</p><p>例如，安装 httpd 和 mlocate（按顺序），输入。</p><pre><code># yum -y install httpd mlocate
</code></pre><p><strong>注意</strong>: 字符 y 表示绕过执行下载和安装前的确认提示。如果需要提示，你可以不用它。</p><p>默认情况下，yum 将安装与操作系统体系结构相匹配的包，除非通过在包名加入架构名。</p><p>例如，在 64 位系统上，<code>yum install package</code>将安装包的 x86_64 版本，而 <code>yum install package.x86</code>（如果有的话）将安装 32 位的。</p><p>有时，你想安装一个包，但不知道它的确切名称。<code>search all</code> 选项可以在当前启用的软件库中的包名称和包描述中搜索它，或者<code>search</code>选项可以在包名称中搜索。</p><p>比如，</p><pre><code># yum search log
</code></pre><p>将搜索安装的软件库中名字和摘要与该词（log）类似的软件，而</p><pre><code># yum search all log
</code></pre><p>也将在包描述和网址中寻找寻找相同的关键字。</p><p>一旦搜索返回包列表，您可能希望在安装前显示一些信息。这时 info 选项派上了用场：</p><pre><code># yum info logwatch
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/05/Search-Package-Information.png" alt="Search Package Information"></p><p><em>搜索包信息</em></p><p>您可以定期用以下命令检查更新：</p><pre><code># yum check-update
</code></pre><p>上述命令将返回可以更新的所有已安装的软件包。在下图所示的例子中，只有 rhel-7-server-rpms 有可用更新：</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/05/Check-For-Updates.png" alt="Check For Package Updates"></p><p><em>检查包更新</em></p><p>然后，您可以更新该包，</p><pre><code># yum update rhel-7-server-rpms
</code></pre><p>如果有几个包可以一同更新，可以使用 <code> yum update</code> 一次性更新所有的包。</p><p>当你知道一个可执行文件的名称，如 ps2pdf，但不知道那个包提供了它？你可以通过 <code>yum whatprovides “*/[executable]”</code>找到:</p><pre><code># yum whatprovides “*/ps2pdf”
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/05/Find-Package-Information.png" alt="Find Package Belongs to Which Package"></p><p><em>查找文件属于哪个包</em></p><p>当删除包时，你可以使用 <code>yum remove Package</code> ，很简单吧？Yum 是一个完整而强大的包管理器。</p><pre><code># yum remove httpd
</code></pre>`,37)),o("ul",null,[o("li",null,[e[1]||(e[1]=t("参见： ",-1)),p(n,{href:"http://www.tecmint.com/20-linux-yum-yellowdog-updater-modified-commands-for-package-mangement/"},{default:r(()=>[...e[0]||(e[0]=[t("20 个管理 RHEL 7 软件包的 Yum 命令",-1)])]),_:1})])]),e[23]||(e[23]=a(`<h3 id="文本式-rpm-工具" tabindex="-1">文本式 RPM 工具 <a class="header-anchor" href="#文本式-rpm-工具" aria-label="Permalink to “文本式 RPM 工具”">​</a></h3><p>RPM（又名 RPM 包管理器，原意是 RedHat 软件包管理器）也可用于安装或更新独立的<code>rpm</code>格式的软件包。</p><p>往往使用 <code>-Uvh</code> 表明如果这个包没有安装就安装它，如果已存在就尝试更新。这里<code>-U</code>表示更新、<code>-v</code>表示显示详细输出，用<code>-h</code>显示进度条。例如</p><pre><code># rpm -Uvh package.rpm
</code></pre><p>rpm 的另一个典型的使用方法是列出所有安装的软件包，</p><pre><code># rpm -qa
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/05/Query-All-RPM-Packages.png" alt="Query All RPM Packages"></p><p><em>查询所有包</em></p>`,8)),o("ul",null,[o("li",null,[e[3]||(e[3]=t("参见： ",-1)),p(n,{href:"http://www.tecmint.com/20-practical-examples-of-rpm-commands-in-linux/"},{default:r(()=>[...e[2]||(e[2]=[t("20 个管理 RHEL 7 软件包的 RPM 命令",-1)])]),_:1})])]),e[24]||(e[24]=a(`<h3 id="使用-cron-调度任务" tabindex="-1">使用 Cron 调度任务 <a class="header-anchor" href="#使用-cron-调度任务" aria-label="Permalink to “使用 Cron 调度任务”">​</a></h3><p>Linux 和 UNIX 类操作系统包括一个称为 Cron 的工具，允许你周期性调度任务（即命令或 shell 脚本）。cron 会每分钟定时检查 /var/spool/cron 目录中有在 /etc/passwd 帐户文件中指定用户名的文件。</p><p>执行命令时，命令输出是发送到该 crontab 的所有者（或者可以在 /etc/crontab，通过 MAILTO 环境变量中指定用户）。</p><p>crontab 文件（可以通过键入 <code>crontab -e</code>并按 Enter 键创建）的格式如下：</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/05/Crontab-Format.png" alt="Crontab Entries"></p><p><em>crontab条目</em></p><p>因此，如果我们想在每个月第二天上午2:15更新本地文件数据库（用于按名字或通配模式定位文件），我们需要添加以下 crontab 条目：</p><pre><code>15 02 2 * * /bin/updatedb
</code></pre><p>以上的条目的意思是：”每年每月第二天的凌晨 2：15 运行 /bin/updatedb，无论是周几”，我想你也猜到了。星号作为通配符。</p><p>正如我们前面所提到的，添加一个 cron 任务后，你可以看到一个名为 root 的文件被添加在 /var/spool/cron。该文件列出了所有的 crond 守护进程应该运行的任务：</p><pre><code># ls -l /var/spool/cron
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/05/Check-All-Cron-Jobs.png" alt="Check All Cron Jobs"></p><p><em>检查所有cron任务</em></p><p>在上图中，显示当前用户的 crontab 可以使用 <code>cat /var/spool/cron</code> 或</p><pre><code># crontab -l
</code></pre><p>如果你需要在一个更精细的时间上运行的任务（例如，一天两次或每月三次），cron 也可以做到。</p><p>例如，每个月1号和15号运行 /my/script 并将输出导出到 /dev/null （丢弃输出），您可以添加如下两个crontab 条目：</p><pre><code>01 00 1 * * /myscript &gt; /dev/null 2&gt;&amp;1
01 00 15 * * /my/script &gt; /dev/null 2&gt;&amp;1
</code></pre><p>不过为了简单，你可以将他们合并：</p><pre><code>01 00 1,15 * *  /my/script &gt; /dev/null 2&gt;&amp;1
</code></pre><p>跟着前面的例子，我们可以在每三个月的第一天的凌晨1：30运行 /my/other/script。</p><pre><code>30 01 1 1,4,7,10 * /my/other/script &gt; /dev/null 2&gt;&amp;1
</code></pre><p>但是当你必须每隔某分钟、小时、天或月来重复某个任务时，你可以通过所需的频率来划分正确的时间。以下与前一个 crontab 条目具有相同的意义：</p><pre><code>30 01 1 */3 * /my/other/script &gt; /dev/null 2&gt;&amp;1
</code></pre><p>或者也许你需要在一个固定的频率或系统启动后运行某个固定的工作，你可以使用下列五个字符串中的一个字符串来指示你想让你的任务计划工作的确切时间：</p><pre><code>@reboot    	仅系统启动时运行
@yearly    	一年一次, 类似与 00 00 1 1 *
@monthly   	一月一次, 类似与 00 00 1 * *
@weekly    	一周一次, 类似与 00 00 * * 0
@daily     	一天一次, 类似与 00 00 * * *
@hourly    	一小时一次, 类似与 00 * * * *
</code></pre>`,26)),o("ul",null,[o("li",null,[e[5]||(e[5]=t("参见：",-1)),p(n,{href:"http://www.tecmint.com/11-cron-scheduling-task-examples-in-linux/"},{default:r(()=>[...e[4]||(e[4]=[t("11 个在 RHEL7 中调度任务的命令",-1)])]),_:1})])]),e[25]||(e[25]=o("h3",{id:"定位和查看日志",tabindex:"-1"},[t("定位和查看日志### "),o("a",{class:"header-anchor",href:"#定位和查看日志","aria-label":"Permalink to “定位和查看日志###”"},"​")],-1)),e[26]||(e[26]=o("p",null,"系统日志存放（并轮转）在 /var/log 目录。根据 Linux 的文件系统层次标准（Linux Filesystem Hierarchy Standard），这个目录包括各种日志文件，并包含一些必要的子目录（如 audit、 httpd 或 samba ，如下图)，并由相应的系统守护进程操作：",-1)),e[27]||(e[27]=o("pre",null,[o("code",null,`# ls /var/log
`)],-1)),e[28]||(e[28]=o("p",null,[o("img",{src:"http://www.tecmint.com/wp-content/uploads/2015/05/Linux-Log-Files.png",alt:"Linux Log Files Location"})],-1)),e[29]||(e[29]=o("p",null,[o("em",null,"Linux 日志的位置")],-1)),o("p",null,[e[7]||(e[7]=t("其他感兴趣的日志比如 ",-1)),p(n,{href:"http://www.tecmint.com/dmesg-commands/"},{default:r(()=>[...e[6]||(e[6]=[t("dmesg",-1)])]),_:1}),e[8]||(e[8]=t("（包括了所有内核层缓冲区的消息），secure（记录要求用户认证的连接请求)，messages（系统级信息），和 wtmp（记录了所有用户的登录、登出）。",-1))]),e[30]||(e[30]=a(`<p>日志是非常重要的，它们让你可以看到任何时刻发生在你的系统的事情，以及已经过去的事情。他们是无价的工具，可以排错和监测一个 Linux 服务器，通常使用 <code>tail -f</code> 命令来实时显示正在发生和写入日志的事件。</p><p>举个例子，如果你想看你的内核相关的日志，你需要输入如下命令：</p><pre><code># tail -f /var/log/dmesg
</code></pre><p>同样的，如果你想查看你的 Web 服务器日志，你需要输入如下命令：</p><pre><code># tail -f /var/log/httpd/access.log
</code></pre><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>如果你知道如何有效的管理包、调度任务、以及知道在哪寻找系统当前和过去操作的信息，你可以放松工作而不会总被吓到。我希望这篇文章能够帮你学习或回顾这些基础知识。</p><p>如果你有任何问题或意见，请使用下面的表单反馈给我们。</p><hr>`,9)),o("p",null,[e[10]||(e[10]=t("via: ",-1)),p(n,{href:"http://www.tecmint.com/yum-package-management-cron-job-scheduling-monitoring-linux-logs/"},{default:r(()=>[...e[9]||(e[9]=[t("http://www.tecmint.com/yum-package-management-cron-job-scheduling-monitoring-linux-logs/",-1)])]),_:1})]),o("p",null,[e[14]||(e[14]=t("作者：",-1)),p(n,{href:"http://www.tecmint.com/author/gacanepa/"},{default:r(()=>[...e[11]||(e[11]=[t("Gabriel Cánepa",-1)])]),_:1}),e[15]||(e[15]=t(" 译者：",-1)),p(n,{href:"https://github.com/xiqingongzi"},{default:r(()=>[...e[12]||(e[12]=[t("xiqingongzi",-1)])]),_:1}),e[16]||(e[16]=t(" 校对：",-1)),p(n,{href:"https://github.com/wxy"},{default:r(()=>[...e[13]||(e[13]=[t("wxy",-1)])]),_:1})]),o("p",null,[e[19]||(e[19]=t("本文由 ",-1)),p(n,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...e[17]||(e[17]=[t("LCTT",-1)])]),_:1}),e[20]||(e[20]=t(" 原创翻译，",-1)),p(n,{href:"https://linux.cn/"},{default:r(()=>[...e[18]||(e[18]=[t("Linux中国",-1)])]),_:1}),e[21]||(e[21]=t(" 荣誉推出",-1))])])}const T=l(s,[["render",c]]);export{f as __pageData,T as default};
